/usr/bin/bash -lc "perl -e '
use strict; use warnings;
my %conf;
for my "'$f (glob("/tmp/pepquery_validation/*.tsv")) {
 open my $fh,"<",$f or die $!; my $head=<$fh>; chomp $head; my @hh=split /'"\\t/,"'$head,-1; my %ix; @ix{@hh}=(0..$#hh);
 while(<$fh>){chomp; my @x=split /'"\\t/,"'$_,-1; $conf{uc $x[$ix{peptide}]}=1 if $x[$ix{confident}] eq "Yes";}
}
my %a;
my @reports=(
 ["SGPS","/workspace/data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular","Protein(s)"],
 ["MaxQuant","/workspace/data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular","Proteins"]
);
for my $spec (@reports){my($src,$f,$pc)=@$spec; open my $fh,"<",$f or die $!; my $head=<$fh>; chomp $head; $head=~s/'"\\r"'$//; my @hh=split /'"\\t/,"'$head,-1; my %ix; @ix{@hh}=(0..$#hh);
 while(<$fh>){chomp; s/'"\\r"'$//; my @x=split /'"\\t/,"'$_,-1; my $p=uc($x[$ix{Sequence}]//""); next unless $conf{$p}; for my $id (split /;/,($x[$ix{$pc}]//"")){ $id=~s/''^'"\\s+|\\s+"'$//g; $a{$p}{$src}{$id}=1 if length $id; }}
}
my($pairs,$missing)=(0,0); for my $p(sort keys %conf){my %u; my @parts; for my $src(qw(SGPS MaxQuant)){my @v=sort keys %{$a{$p}{$src}//{}}; $u{$_}=1 for @v; push @parts, "$src=".join(",",@v);} $pairs+=keys %u; $missing++ unless keys %u; print join("'"\\t\","'$p,@parts),"'"\\n\";} print STDERR \"verified=\".(keys %conf).\" pairs="'$pairs missing=$missing'"\\n\";
'"

